using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.Text;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;
    private readonly string _tempRoot;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _envMock = new Mock<IWebHostEnvironment>();
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _tempRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(_tempRoot);
        _envMock.Setup(e => e.WebRootPath).Returns(_tempRoot);
        _envMock.Setup(e => e.ContentRootPath).Returns(_tempRoot);
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
    }

    [Fact]
    public void Index_ReturnsCoursesList()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var courses = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, courses.Count);
    }

    [Fact]
    public void Details_ValidId_ReturnsCourse()
    {
        var result = _controller.Details(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Intro to CS", course.Title);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsView()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Course>(result.Model);
    }

    [Fact]
    public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 2001,
            Title = "New Course",
            Credits = 3,
            DepartmentID = 1
        };

        var result = _controller.Create(course, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Courses.Count());
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 2002, Title = "", Credits = 3, DepartmentID = 1 };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Post_InvalidFileExtension_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 2003, Title = "Test", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile("test.exe", 1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 2004, Title = "Test", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile("big.jpg", 6 * 1024 * 1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"]!.Errors.First();
        Assert.Contains("5MB", error.ErrorMessage);
    }

    [Fact]
    public void Create_Post_ValidImage_UploadsAndRedirects()
    {
        var course = new Course { CourseID = 2005, Title = "WithImage", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile("photo.png", 1024);

        var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var savedCourse = _context.Courses.Find(2005);
        Assert.NotNull(savedCourse!.TeachingMaterialImagePath);
        Assert.Contains("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsCourse()
    {
        var result = _controller.Edit(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Intro to CS", course.Title);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        var course = _context.Courses.Find(1001)!;
        course.Title = "Updated CS";
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(course, null!) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 1001, Title = "Test", Credits = 3, DepartmentID = 1 };
        _context.Entry(_context.Courses.Find(1001)!).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        var fileMock = CreateMockFile("bad.txt", 1024);

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsCourse()
    {
        var result = _controller.Delete(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Intro to CS", course.Title);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourse()
    {
        var result = _controller.DeleteConfirmed(1001) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Courses.Find(1001));
    }

    private static Mock<IFormFile> CreateMockFile(string fileName, long length)
    {
        var mock = new Mock<IFormFile>();
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);
        var content = new byte[Math.Min(length, 100)];
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>()))
            .Callback<Stream>(s => s.Write(content, 0, content.Length));
        return mock;
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        if (Directory.Exists(_tempRoot))
            Directory.Delete(_tempRoot, true);
    }
}

