[Fact]
public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
{
    // Drain any notifications from other tests (static queue)
    while (true)
    {
        var jsonDrain = _controller.GetNotifications() as JsonResult;
        var drainValue = jsonDrain!.Value;
        var drainCountProp = drainValue!.GetType().GetProperty("count");
        if ((int)drainCountProp!.GetValue(drainValue)! == 0) break;
    }

    var result = _controller.GetNotifications();

    Assert.NotNull(result);
    var jsonResult = result as JsonResult;
    Assert.NotNull(jsonResult);
    var value = jsonResult.Value;
    Assert.NotNull(value);
    var successProp = value.GetType().GetProperty("success");
    Assert.True((bool)successProp!.GetValue(value)!);
    var countProp = value.GetType().GetProperty("count");
    Assert.Equal(0, (int)countProp!.GetValue(value)!);
}

