using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First(s => s.LastName == "Test");
        Assert.Equal("User", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department { Name = "Test Dept", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 9001, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Find(9001);
        Assert.NotNull(retrieved);
        Assert.Equal("Test Course", retrieved.Title);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            LastName = "Professor",
            FirstMidName = "Test",
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.First(i => i.LastName == "Professor");
        Assert.Equal("Test", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddDepartmentWithAdministrator()
    {
        var instructor = new Instructor
        {
            LastName = "Admin",
            FirstMidName = "Dept",
            HireDate = new DateTime(2015, 6, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var dept = new Department
        {
            Name = "Engineering",
            Budget = 200000,
            StartDate = new DateTime(2010, 9, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.Include(d => d.Administrator).First(d => d.Name == "Engineering");
        Assert.NotNull(retrieved.Administrator);
        Assert.Equal("Admin", retrieved.Administrator.LastName);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var instructor = new Instructor { LastName = "Key", FirstMidName = "Test", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        var dept = new Department { Name = "KeyDept", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 8001, Title = "KeyCourse", Credits = 2, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = 8001 };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.Find(8001, instructor.ID);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void OfficeAssignment_HasInstructorAsPrimaryKey()
    {
        var instructor = new Instructor { LastName = "Office", FirstMidName = "Test", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Building A" };
        _context.OfficeAssignments.Add(office);
        _context.SaveChanges();

        var retrieved = _context.OfficeAssignments.Find(instructor.ID);
        Assert.NotNull(retrieved);
        Assert.Equal("Building A", retrieved.Location);
    }

    [Fact]
    public void Enrollment_TracksGrade()
    {
        var student = new Student { LastName = "Grade", FirstMidName = "Test", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "GradeDept", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7001, Title = "GradeCourse", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { CourseID = 7001, StudentID = student.ID, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.First(e => e.StudentID == student.ID);
        Assert.Equal(Grade.A, retrieved.Grade);
    }

    [Fact]
    public void Enrollment_GradeCanBeNull()
    {
        var student = new Student { LastName = "NoGrade", FirstMidName = "Test", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var dept = new Department { Name = "NGDept", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7002, Title = "NoGradeCourse", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { CourseID = 7002, StudentID = student.ID, Grade = null };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.First(e => e.CourseID == 7002);
        Assert.Null(retrieved.Grade);
    }

    [Fact]
    public void Person_FullName_ReturnsConcatenation()
    {
        var student = new Student { LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now };

        Assert.Equal("Doe, Jane", student.FullName);
    }

    [Fact]
    public void TPH_StudentsAndInstructors_SharePersonTable()
    {
        var student = new Student { LastName = "TPH", FirstMidName = "Student", EnrollmentDate = DateTime.Now };
        var instructor = new Instructor { LastName = "TPH", FirstMidName = "Instructor", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Students.Add(student);
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        // Both should be in People
        var people = _context.People.Where(p => p.LastName == "TPH").ToList();
        Assert.Equal(2, people.Count);
    }

    public void Dispose()
    {
        _context.Dispose();
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerEdgeCaseTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerEdgeCaseTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _controller = new StudentsController(_context);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
    }

    [Fact]
    public void Create_Post_ModelStateInvalid_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            LastName = "",
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Same(student, result.Model);
    }

    [Fact]
    public void Index_Pagination_RespectsPageSize()
    {
        // Add more students to exceed page size of 10
        for (int i = 100; i < 115; i++)
        {
            _context.Students.Add(new Student
            {
                ID = i,
                LastName = $"Student{i}",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 1, 1)
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 1) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(10, model.Count);
        Assert.True(model.HasNextPage);
    }

    [Fact]
    public void Index_Pagination_SecondPage()
    {
        for (int i = 100; i < 115; i++)
        {
            _context.Students.Add(new Student
            {
                ID = i,
                LastName = $"Student{i}",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 1, 1)
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 2) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        // Total is 18 (3 seed + 15 added), page 2 with pageSize 10 should have 8
        Assert.Equal(8, model.Count);
        Assert.False(model.HasNextPage);
    }

    [Fact]
    public void Index_ViewBag_SetsCurrentSort()
    {
        _controller.Index("name_desc", null, null, null);

        Assert.Equal("name_desc", _controller.ViewBag.CurrentSort);
    }

    [Fact]
    public void Index_ViewBag_SetsSortParameters()
    {
        _controller.Index(null, null, null, null);

        // When sortOrder is empty, NameSortParm should be "name_desc"
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_ViewBag_DateSortParm_WhenDateSort()
    {
        _controller.Index("Date", null, null, null);

        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_ViewBag_CurrentFilter_SetFromSearchString()
    {
        _controller.Index(null, null, "test", null);

        Assert.Equal("test", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Edit_Post_DateOutOfRange_FutureDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 10,
            LastName = "Adams",
            FirstMidName = "Alice",
            EnrollmentDate = new DateTime(1000, 1, 1) // Before 1753
        };
        _context.Entry(_context.Students.Find(10)!).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerEdgeCaseTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly string _tempRoot;

    public CoursesControllerEdgeCaseTests()
    {
        _context = TestDbContextFactory.CreateWithSeedData();
        _envMock = new Mock<IWebHostEnvironment>();
        _tempRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(_tempRoot);
        _envMock.Setup(e => e.WebRootPath).Returns(_tempRoot);
        _envMock.Setup(e => e.ContentRootPath).Returns(_tempRoot);
        var loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, loggerMock.Object);
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_Succeed(string ext)
    {
        var course = new Course { CourseID = 3000 + ext.GetHashCode(), Title = $"Course{ext}", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile($"img{ext}", 1024);

        var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Theory]
    [InlineData(".pdf")]
    [InlineData(".exe")]
    [InlineData(".doc")]
    [InlineData(".svg")]
    public void Create_Post_DisallowedExtensions_Fail(string ext)
    {
        var course = new Course { CourseID = 4000 + Math.Abs(ext.GetHashCode()), Title = $"Bad{ext}", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile($"file{ext}", 1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_ExactlyAtSizeLimit_Succeeds()
    {
        var course = new Course { CourseID = 5001, Title = "AtLimit", Credits = 3, DepartmentID = 1 };
        // Exactly 5MB should still be rejected (> is the check but it's Length > 5 * 1024 * 1024)
        var fileMock = CreateMockFile("exact.jpg", 5 * 1024 * 1024);

        var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

        // Exactly 5MB passes since the check is > not >=
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_Post_JustOverSizeLimit_Fails()
    {
        var course = new Course { CourseID = 5002, Title = "OverLimit", Credits = 3, DepartmentID = 1 };
        var fileMock = CreateMockFile("big.jpg", 5 * 1024 * 1024 + 1);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsError()
    {
        var course = new Course { CourseID = 1001, Title = "Updated", Credits = 3, DepartmentID = 1 };
        var tracked = _context.Courses.Find(1001);
        if (tracked != null) _context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        var fileMock = CreateMockFile("bad.zip", 1024);

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_FileTooLarge_ReturnsError()
    {
        var course = new Course { CourseID = 1001, Title = "Updated", Credits = 3, DepartmentID = 1 };
        var tracked = _context.Courses.Find(1001);
        if (tracked != null) _context.Entry(tracked).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        var fileMock = CreateMockFile("big.jpg", 10 * 1024 * 1024);

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
